installer-gui-script.script:
function logatlas_check() {
    var v = system.version.ProductVersion;
    if (system.compareVersions(v, '12.0') < 0) {
        my.result.type = 'Fatal';
        my.result.title = 'Нужна macOS 12 или новее';
        my.result.message = 'На этом компьютере macOS ' + v + ', а LogAtlas работает начиная с macOS 12 (Monterey).';
        return false;
    }
    var apple_silicon = false;
    try { apple_silicon = (system.sysctl('hw.optional.arm64') == 1); } catch (e) { apple_silicon = false; }
    var need_apple_silicon = ('@ARCH@' == 'arm64');
    if (need_apple_silicon && !apple_silicon) {
        // сборка для Apple Silicon на Intel не запустится вовсе
        my.result.type = 'Fatal';
        my.result.title = 'Установщик для другого процессора';
        my.result.message = 'Это сборка для Mac на Apple Silicon (M1–M4), а здесь процессор Intel. ' +
            'Скачайте LogAtlas-@VERSION@-macos-x86_64.pkg.';
        return false;
    }
    if (!need_apple_silicon && apple_silicon) {
        // сборка для Intel на Apple Silicon работает через Rosetta — предупреждаем, но не мешаем
        my.result.type = 'Warn';
        my.result.title = 'Есть сборка для вашего процессора';
        my.result.message = 'Это сборка для Mac на Intel. Она заработает через Rosetta, но для Apple Silicon ' +
            'есть отдельная: LogAtlas-@VERSION@-macos-arm64.pkg — она быстрее.';
        return false;
    }
    return true;
}
